-- Context isolation baseline only; no grants or complete user/branch authorization.
-- A trusted API sets context only AFTER authenticating and validating memberships.
-- End-user SQL clients must not have credentials to this service role.
SET search_path = plato_draft, public;
CREATE FUNCTION plato_draft.context_tenant() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('app.tenant_id', true),'')::uuid
$$;
CREATE FUNCTION plato_draft.context_restaurant() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('app.restaurant_id', true),'')::uuid
$$;
CREATE FUNCTION plato_draft.context_user() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('app.user_id', true),'')::uuid
$$;
